-- (16 Okt 2026) SPDT NTP 2026 -- ISI Lembar Pendataan: 811 KK dari berkas "SPDT_NTP_Maps_DSRT.xlsx" (sheet Maps).
-- Jalankan SETELAH 20261016a_spdt_ntp_lembar_pendataan.sql. Dijalankan sendiri oleh pemilik di Supabase > SQL Editor.
-- Aman diulang: bila tabel sudah berisi, skrip berhenti tanpa mengubah apa pun. Satu transaksi; jumlah baris diperiksa di akhir.
-- Pemetaan nama Excel -> akun: PPL cocok persis dengan nama akun; PML dipetakan eksplisit
--   (YESSI ADRIANI -> Yesi Adriani 727, APRILLA INSAN SUCI -> Aprila Insan Suci 64, RAHMI FEBRINA SARI -> Rahmi Febrinasari 513, MEGA NANA -> Mega Nana Yulianti 368).
begin;
do $$ begin
  if (select count(*) from public.sigap_spdt_kk) > 0 then raise exception 'sigap_spdt_kk sudah berisi; skrip tidak dijalankan ulang.'; end if;
end $$;

;

do $$
declare n int; tanpa_akun int; tanpa_koord int;
begin
  select count(*) into n from public.sigap_spdt_kk;
  select count(*) into tanpa_akun from public.sigap_spdt_kk where ppl_akun_id is null or pml_akun_id is null;
  select count(*) into tanpa_koord from public.sigap_spdt_kk where lat is null or lng is null;
  if n <> 811 then raise exception 'Jumlah KK % (harapan 811)', n; end if;
  if tanpa_akun <> 0 then raise exception 'Ada % KK tanpa akun PPL/PML', tanpa_akun; end if;
  if tanpa_koord <> 0 then raise exception 'Ada % KK tanpa koordinat', tanpa_koord; end if;
end $$;
commit;
